"""Render the measured duration matrix; no inferred or interpolated rows."""
import json,re
from pathlib import Path
r=Path(__file__).resolve().parent
rows=json.loads((r/'results.json').read_text())
assert len(rows)==30, 'Duration matrix is incomplete'
norm=lambda s:re.findall(r'\w+',s.lower())
lines=['# Duration and RAM comparison', '', 'Measured on Intel i5-12500H and Iris Xe. Gains vary with duration and content. These five exact-duration clips are prefixes of one synthetic recording. This tests scaling, not broad recognition accuracy. No user audio was used.', '', 'Each baseline/candidate/duration uses a fresh process, one warmup transcription and two measured transcriptions. Times are the median of those two warm calls, excluding model loading and audio capture. Baseline always runs before candidate, so workstation load and run order remain possible sources of noise. Raw sample times are in `duration/results.json`.', '', 'RAM columns are MiB. Baseline and candidate process values are peak resident process RAM across loading and all three calls. GPU values are peak resident DRM buffers sampled every 100 ms, with duplicate client IDs removed. GPU buffers use system RAM on Iris Xe and are mostly absent from process RSS. Keep these measures separate: peaks can occur at different times and shared mappings may overlap. This excludes the GUI and whole-application overhead. RAM was measured, not optimized.', '']
for model,label in [('canary','Canary 180m Flash Q8'),('parakeet','Parakeet Unified English 0.6b Q8'),('whisper','Whisper base.en INT8, beam 5, VAD on')]:
 lines += ['## '+label,'','| Clip | Baseline time | Candidate time | Speedup | Baseline process RAM | Candidate process RAM | Candidate GPU RAM | Same words? |','|---:|---:|---:|---:|---:|---:|---:|:---:|']
 for duration in [2,5,15,30,60]:
  b=next(x for x in rows if x['model']==model and x['duration_s']==duration and x['variant']=='baseline');c=next(x for x in rows if x['model']==model and x['duration_s']==duration and x['variant']=='candidate')
  lines.append(f"| {duration} s | {b['warm_seconds']:.3f} s | {c['warm_seconds']:.3f} s | {b['warm_seconds']/c['warm_seconds']:.2f}x | {b['peak_process_mib']:.0f} | {c['peak_process_mib']:.0f} | {c['sampled_peak_gpu_resident_mib']:.0f} | {'Yes' if norm(b['text'])==norm(c['text']) else '**No**'} |")
 lines+=['']
 if model=='canary':lines+=['Baseline is CPU with eight threads. Candidate uses Vulkan encoder, CPU decoder, the direct pre-depthwise prototype, F32 Vulkan operations, and eight P-core hardware threads with OpenMP workers paused after each call. Both retain quiet-boundary chunking at at most 30 seconds. A 60-second clip can use less peak RAM than the 30-second clip because the chosen quiet boundaries make its largest chunk shorter. The candidate is slower on the two-second median in this run, with substantial timing variation.','']
 if model=='parakeet':lines+=['Baseline is CPU with eight threads. Candidate uses the existing Vulkan backend with eight threads and unchanged weights. Both use one continuous stream per clip with 5600/1040/1040 ms left/chunk/right context. The benchmark feeds audio without real-time delays, so these are total compute times, not the delay after releasing the recording key. Longer clips are not split into independent 30-second streams.','']
 if model=='whisper':lines+=['Baseline is the application CTranslate2 path with four CPU threads. Candidate uses eight P-core hardware threads and skips FFTs for empty padding. Only speech segments of at most five seconds use the shorter ten-second encoder context; longer segments retain the original thirty-second context. Both retain beam size 5, INT8 and VAD. Thus the large short-clip gain should not be expected for 15–60 seconds. Neither uses the Intel GPU.','']
lines+=['## Limits and evidence','','Short Canary and longer Whisper measurements are noisy. Canary at two seconds measured 0.268 and 0.119 seconds in the candidate, versus 0.138 and 0.136 in the baseline. Whisper at sixty seconds measured 3.402 and 4.429 seconds in the candidate, versus 3.467 and 3.517 in the baseline. Treat the displayed ratios as this run’s rough results, not stable performance guarantees. In particular, there is no demonstrated long-clip Whisper win across all durations.','','Matching words means lowercase alphanumeric token sequences agree between baseline and candidate. It does not establish correctness against a reference. Inspect the saved transcripts before adoption; earlier human-speech results and rejected Whisper padding settings are summarized in [README.md](README.md).','', 'The candidate implementations remain isolated prototypes. The required application tests, Clippy, Python checks, release build and native probe passed; selected native screenshots were inspected. No application configuration or installed engine was changed.','', 'Raw evidence: [results.json](duration/results.json), per-call JSONL and stderr files in `duration/`, and [fixture hashes](duration/fixtures.json). GPU accounting follows the kernel [DRM usage-statistics interface](https://www.kernel.org/doc/html/v6.9/gpu/drm-usage-stats.html).']
(r.parent/'DURATION_REPORT.md').write_text('\n'.join(lines)+'\n')
